import fs from 'node:fs';
import { tmpdir } from 'node:os';
import { join } from 'node:path';
import { pathToFileURL } from 'node:url';
import { createRequire } from 'node:module';
const root = fs.realpathSync(fs.mkdtempSync(join(tmpdir(), 'home-module-url-')));
try {
  fs.writeFileSync(join(root, 'dependency.cjs'), 'module.exports = { value: 42 };\n');
  const require = createRequire(pathToFileURL(join(root, 'entry.cjs')));
  if (require('./dependency.cjs').value !== 42 || require.resolve('./dependency.cjs') !== join(root, 'dependency.cjs')) throw new Error('Native URL referrer did not load the actual relative dependency');
  console.log('NATIVE URL CREATEREQUIRE ACTUAL DEPENDENCY OK');
} finally { fs.rmSync(root, { recursive: true, force: true }); }
